
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_ncap_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_ncap", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.378512975221367e+00, -4.295958342214147e+00, -4.180372070374583e+00, -4.020452959683440e+00, -3.802962819165537e+00, -3.514402700092227e+00, -3.144935268432861e+00, -2.695386532884988e+00, -2.186075623819431e+00, -1.656920753947818e+00, -1.129775218561908e+00, -7.512049545688615e-01, -6.487193783940315e-01, -5.365805049214460e-01, -3.919422138580428e-01, -2.546847735135505e-01, -1.675810533879676e-01, -1.673925546314995e-01, -2.584034822306142e-01, -5.123930487994213e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


